    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_A_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_A_D_IceLaneA, VEGA_KEY_A_D_IceLaneB, VEGA_KEY_A_D_IceLaneC, VEGA_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Vega_Arx::KEY_A_E_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_A_E_B(PARAMS_SEED);

    KeyDiffuse_A_A_E(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_A_E_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_A_E_D(PARAMS_SEED);

    KeyDiffuse_B_A_E(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_A_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_A_E_IceLaneA, VEGA_KEY_A_E_IceLaneB, VEGA_KEY_A_E_IceLaneC, VEGA_KEY_A_E_IceLaneD, &(pWorkSpace->mKeyBoxA[4U][0]));

    // Key flow — A / F

    //
    // src: [$earth, $crystal]
