    TwistExpander_Vega_Arx::KEY_A_F_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_A_F_B(PARAMS_SEED);

    KeyDiffuse_A_A_F(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
