    TwistExpander_Vega_Arx::KEY_A_F_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_A_F_D(PARAMS_SEED);

    KeyDiffuse_B_A_F(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
