    TwistSquash::SquashKeyA(VEGA_KEY_A_F_IceLaneA, VEGA_KEY_A_F_IceLaneB, VEGA_KEY_A_F_IceLaneC, VEGA_KEY_A_F_IceLaneD, &(pWorkSpace->mKeyBoxA[5U][0]));

    // Key flow — A / G

