    TwistSquash::SquashKeyA(VEGA_KEY_B_A_IceLaneA, VEGA_KEY_B_A_IceLaneB, VEGA_KEY_B_A_IceLaneC, VEGA_KEY_B_A_IceLaneD, &(pWorkSpace->mKeyBoxB[0U][0]));

    // Key flow — B / B

    //
    // src: [$earth, $crystal]
