    TwistSquash::SquashKeyA(VEGA_KEY_B_C_IceLaneA, VEGA_KEY_B_C_IceLaneB, VEGA_KEY_B_C_IceLaneC, VEGA_KEY_B_C_IceLaneD, &(pWorkSpace->mKeyBoxB[2U][0]));

    // Key flow — B / D

    //
    // src: [$earth, $crystal]
