    //
    TwistExpander_Vega_Arx::KEY_B_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_B_D_D(PARAMS_SEED);

    KeyDiffuse_B_B_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_B_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_B_D_IceLaneA, VEGA_KEY_B_D_IceLaneB, VEGA_KEY_B_D_IceLaneC, VEGA_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

    // Key flow — B / E

