    KeyDiffuse_A_B_E(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_B_E_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_B_E_D(PARAMS_SEED);

    KeyDiffuse_B_B_E(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_B_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_B_E_IceLaneA, VEGA_KEY_B_E_IceLaneB, VEGA_KEY_B_E_IceLaneC, VEGA_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

    // Key flow — B / F

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
