    TwistExpander_Vega_Arx::KEY_B_F_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_B_F_B(PARAMS_SEED);

    KeyDiffuse_A_B_F(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_B_F_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_B_F_D(PARAMS_SEED);

    KeyDiffuse_B_B_F(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_B_F_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_B_F_IceLaneA, VEGA_KEY_B_F_IceLaneB, VEGA_KEY_B_F_IceLaneC, VEGA_KEY_B_F_IceLaneD, &(pWorkSpace->mKeyBoxB[5U][0]));

    // Key flow — B / G

    //
    // src: [$earth, $crystal]
