    TwistSquash::SquashKeyA(VEGA_KEY_B_G_IceLaneA, VEGA_KEY_B_G_IceLaneB, VEGA_KEY_B_G_IceLaneC, VEGA_KEY_B_G_IceLaneD, &(pWorkSpace->mKeyBoxB[6U][0]));

